{
  "name": "Research Approval Workflow",
  "description": "A comprehensive 4-stage research application approval system featuring roles for Applicants, Reviewers, HOD, and Director, with automated status tracking and AI-assisted review capabilities."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum UserRole {
  APPLICANT = 'APPLICANT',
  REVIEWER_1 = 'REVIEWER_1',
  REVIEWER_2 = 'REVIEWER_2',
  REVIEWER_3 = 'REVIEWER_3',
  HOD = 'HOD',
  DIRECTOR = 'DIRECTOR'
}

export enum ApplicationStatus {
  SUBMITTED = 'SUBMITTED',
  UNDER_REVIEW = 'UNDER_REVIEW',
  HOD_PENDING = 'HOD_PENDING',
  DIRECTOR_PENDING = 'DIRECTOR_PENDING',
  APPROVED = 'APPROVED',
  REJECTED = 'REJECTED'
}

export enum ReviewRating {
  EXCELLENT = 'Excellent',
  GOOD = 'Good',
  NEEDS_CORRECTIONS = 'Needs Corrections'
}

export interface TeamMember {
  name: string;
  position: string;
  idCard: string;
}

export interface ReviewData {
  reviewerId: string;
  comments: string;
  status: ReviewRating;
  date: string;
}

export interface Application {
  id: string;
  // Applicant Info
  applicantName: string;
  applicantIdCard: string;
  applicantEmail: string;
  applicantPhone: string;
  teamName: string;
  teamMembers: TeamMember[];

  // Research Info
  researchTitle: string;
  researchLink: string;

  // Event Info
  eventName: string;
  eventLocation: string;
  eventDate: string;
  eventLevel: 'National' | 'International';

  // Submission Info
  submissionDate: string;
  status: ApplicationStatus;

  // Workflow Progress
  selectedReviewers: string[]; // List of Reviewer IDs chosen
  reviews: Record<string, ReviewData>; // Keyed by reviewer role name

  hodStatus: 'Supported' | 'Unsupported' | null;
  hodComments: string;
  hodDate: string | null;

  directorStatus: 'Approved' | 'Unapproved' | null;
  directorComments: string;
  directorDate: string | null;
}

export const REVIEWER_LIST = ['Dr. Sarah Smith', 'Prof. John Doe', 'Dr. Emily Brown', 'Dr. Michael Chen', 'Prof. Lisa Wong'];

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function suggestResearchImprovements(title: string, link: string) {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `
        As an academic reviewer, provide 3 brief bullet points to improve a research paper 
        titled "${title}". 
        Even though you can't access the link "${link}" directly, provide general 
        best-practice suggestions based on common pitfalls in such research fields.
      `,
      config: {
        thinkingConfig: { thinkingBudget: 0 }
      }
    });
    return response.text || "No suggestions available at this time.";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "AI Assistant is currently unavailable. Please provide manual feedback.";
  }
}

import React, { useState, useEffect } from 'react';
import { UserRole, Application, ApplicationStatus } from './types';
import Dashboard from './components/Dashboard';
import ApplicationWizard from './components/ApplicationWizard';
import RoleSwitcher from './components/RoleSwitcher';

const App: React.FC = () => {
  const [currentUserRole, setCurrentUserRole] = useState<UserRole>(UserRole.APPLICANT);
  const [applications, setApplications] = useState<Application[]>([]);
  const [isCreating, setIsCreating] = useState(false);

  // Load mock data or initial state
  useEffect(() => {
    const saved = localStorage.getItem('research_apps');
    if (saved) {
      setApplications(JSON.parse(saved));
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('research_apps', JSON.stringify(applications));
  }, [applications]);

  const handleCreateApplication = (newApp: Application) => {
    setApplications(prev => [newApp, ...prev]);
    setIsCreating(false);
  };

  const updateApplication = (updatedApp: Application) => {
    setApplications(prev => prev.map(app => app.id === updatedApp.id ? updatedApp : app));
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 px-6 py-4 flex justify-between items-center sticky top-0 z-50">
        <div className="flex items-center gap-3">
          <div className="bg-indigo-600 p-2 rounded-lg">
            <i className="fas fa-file-signature text-white text-xl"></i>
          </div>
          <div>
            <h1 className="font-bold text-xl text-slate-800 tracking-tight">ResFlow</h1>
            <p className="text-xs text-slate-500 font-medium uppercase tracking-wider">Research Approval System</p>
          </div>
        </div>

        <div className="flex items-center gap-6">
          <RoleSwitcher currentRole={currentUserRole} onRoleChange={setCurrentUserRole} />
          <div className="h-8 w-[1px] bg-slate-200 hidden md:block"></div>
          <div className="hidden md:flex items-center gap-2">
            <div className="w-8 h-8 rounded-full bg-slate-200 flex items-center justify-center text-slate-600 font-bold text-sm">
              {currentUserRole.charAt(0)}
            </div>
            <span className="text-sm font-medium text-slate-700">{currentUserRole.replace('_', ' ')}</span>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 container mx-auto px-4 py-8 max-w-7xl">
        {isCreating ? (
          <ApplicationWizard 
            onCancel={() => setIsCreating(false)} 
            onSubmit={handleCreateApplication}
          />
        ) : (
          <Dashboard 
            role={currentUserRole}
            applications={applications}
            onCreateNew={() => setIsCreating(true)}
            onUpdateApplication={updateApplication}
          />
        )}
      </main>

      <footer className="bg-white border-t border-slate-200 py-6 text-center text-slate-500 text-sm">
        &copy; {new Date().getFullYear()} ResFlow Systems. All Rights Reserved.
      </footer>
    </div>
  );
};

export default App;

import React from 'react';
import { UserRole } from '../types';

interface RoleSwitcherProps {
  currentRole: UserRole;
  onRoleChange: (role: UserRole) => void;
}

const RoleSwitcher: React.FC<RoleSwitcherProps> = ({ currentRole, onRoleChange }) => {
  return (
    <div className="relative group">
      <select 
        value={currentRole}
        onChange={(e) => onRoleChange(e.target.value as UserRole)}
        className="appearance-none bg-slate-100 border-none rounded-full px-4 py-2 pr-10 text-sm font-medium text-slate-700 cursor-pointer hover:bg-slate-200 focus:ring-2 focus:ring-indigo-500 transition-all outline-none"
      >
        <option value={UserRole.APPLICANT}>👤 Applicant</option>
        <option value={UserRole.REVIEWER_1}>🔍 Reviewer 1</option>
        <option value={UserRole.REVIEWER_2}>🔍 Reviewer 2</option>
        <option value={UserRole.REVIEWER_3}>🔍 Reviewer 3</option>
        <option value={UserRole.HOD}>🏢 HOD</option>
        <option value={UserRole.DIRECTOR}>🎓 Director</option>
      </select>
      <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">
        <i className="fas fa-chevron-down text-xs"></i>
      </div>
    </div>
  );
};

export default RoleSwitcher;

import React, { useState } from 'react';
import { UserRole, Application, ApplicationStatus } from '../types';
import ApplicationCard from './ApplicationCard';
import StageActions from './StageActions';

interface DashboardProps {
  role: UserRole;
  applications: Application[];
  onCreateNew: () => void;
  onUpdateApplication: (app: Application) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ role, applications, onCreateNew, onUpdateApplication }) => {
  const [selectedApp, setSelectedApp] = useState<Application | null>(null);

  // Filter logic based on requirements: "each stage can only be seen by respective people"
  const filteredApps = applications.filter(app => {
    if (role === UserRole.APPLICANT) return true; // See all your own (in real app, filter by user id)

    if (role === UserRole.REVIEWER_1 || role === UserRole.REVIEWER_2 || role === UserRole.REVIEWER_3) {
      // Must be in reviewer list and application must be submitted/under review
      return app.status === ApplicationStatus.SUBMITTED || app.status === ApplicationStatus.UNDER_REVIEW;
    }

    if (role === UserRole.HOD) {
      // Must have all reviews completed
      return app.status === ApplicationStatus.HOD_PENDING;
    }

    if (role === UserRole.DIRECTOR) {
      // Must be supported by HOD
      return app.status === ApplicationStatus.DIRECTOR_PENDING;
    }

    return false;
  });

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">
            {role === UserRole.APPLICANT ? 'My Applications' : 'Pending Tasks'}
          </h2>
          <p className="text-slate-500">Manage research paper submission and approval cycles.</p>
        </div>
        {role === UserRole.APPLICANT && (
          <button 
            onClick={onCreateNew}
            className="flex items-center justify-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white px-5 py-2.5 rounded-lg font-semibold shadow-sm transition-all"
          >
            <i className="fas fa-plus"></i>
            New Application
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        {/* List */}
        <div className={`${selectedApp ? 'lg:col-span-4' : 'lg:col-span-12'} space-y-4`}>
          {filteredApps.length === 0 ? (
            <div className="bg-white border-2 border-dashed border-slate-200 rounded-xl p-12 text-center">
              <div className="bg-slate-50 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
                <i className="fas fa-inbox text-slate-400 text-2xl"></i>
              </div>
              <h3 className="font-semibold text-slate-800">No applications found</h3>
              <p className="text-slate-500 text-sm mt-1">There are no records matching your role criteria.</p>
            </div>
          ) : (
            filteredApps.map(app => (
              <ApplicationCard 
                key={app.id} 
                app={app} 
                isActive={selectedApp?.id === app.id}
                onClick={() => setSelectedApp(app)} 
              />
            ))
          )}
        </div>

        {/* Details / Action Area */}
        {selectedApp && (
          <div className="lg:col-span-8 bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden flex flex-col min-h-[600px]">
            <div className="p-6 border-b border-slate-100 flex justify-between items-start">
              <div>
                <h3 className="text-xl font-bold text-slate-800">{selectedApp.researchTitle}</h3>
                <p className="text-sm text-slate-500 mt-1">
                  Submitted by <span className="font-semibold text-slate-700">{selectedApp.applicantName}</span> • {new Date(selectedApp.submissionDate).toLocaleDateString()}
                </p>
              </div>
              <button onClick={() => setSelectedApp(null)} className="text-slate-400 hover:text-slate-600 p-2">
                <i className="fas fa-times"></i>
              </button>
            </div>

            <div className="flex-1 p-6 overflow-y-auto space-y-8">
              {/* Common Info Section */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-4">
                  <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider">Research Details</h4>
                  <div className="space-y-2">
                    <p className="text-sm"><span className="text-slate-500">Title:</span> {selectedApp.researchTitle}</p>
                    <p className="text-sm">
                      <span className="text-slate-500">Link:</span>{' '}
                      <a href={selectedApp.researchLink} target="_blank" className="text-indigo-600 hover:underline">
                        View Paper <i className="fas fa-external-link-alt text-xs ml-1"></i>
                      </a>
                    </p>
                  </div>
                </div>
                <div className="space-y-4">
                  <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider">Event Details</h4>
                  <div className="space-y-2">
                    <p className="text-sm"><span className="text-slate-500">Name:</span> {selectedApp.eventName}</p>
                    <p className="text-sm"><span className="text-slate-500">Location:</span> {selectedApp.eventLocation}</p>
                    <p className="text-sm"><span className="text-slate-500">Date:</span> {new Date(selectedApp.eventDate).toLocaleDateString()}</p>
                    <p className="text-sm">
                      <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-slate-100 text-slate-800 border border-slate-200">
                        {selectedApp.eventLevel}
                      </span>
                    </p>
                  </div>
                </div>
              </div>

              {/* Progress Stepper */}
              <div className="py-4 border-t border-b border-slate-100">
                <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-6">Workflow Progress</h4>
                <div className="flex justify-between relative">
                  <div className="absolute top-1/2 left-0 right-0 h-0.5 bg-slate-100 -translate-y-1/2 z-0"></div>
                  {['Submitted', 'Reviewed', 'HOD Support', 'Approved'].map((step, idx) => {
                    const isDone = 
                      (idx === 0) || 
                      (idx === 1 && Object.keys(selectedApp.reviews).length === 3) ||
                      (idx === 2 && selectedApp.hodStatus === 'Supported') ||
                      (idx === 3 && selectedApp.directorStatus === 'Approved');

                    return (
                      <div key={step} className="flex flex-col items-center gap-2 relative z-10">
                        <div className={`w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold transition-colors ${isDone ? 'bg-indigo-600 text-white' : 'bg-white border-2 border-slate-200 text-slate-400'}`}>
                          {isDone ? <i className="fas fa-check"></i> : idx + 1}
                        </div>
                        <span className="text-[10px] font-bold uppercase text-slate-500">{step}</span>
                      </div>
                    );
                  })}
                </div>
              </div>

              {/* Role-Specific Action Section */}
              <div className="bg-slate-50 rounded-xl p-6 border border-slate-200">
                <StageActions 
                  role={role} 
                  app={selectedApp} 
                  onUpdate={(updated) => {
                    onUpdateApplication(updated);
                    setSelectedApp(updated);
                  }} 
                />
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default Dashboard;

import React from 'react';
import { Application, ApplicationStatus } from '../types';

interface ApplicationCardProps {
  app: Application;
  isActive: boolean;
  onClick: () => void;
}

const ApplicationCard: React.FC<ApplicationCardProps> = ({ app, isActive, onClick }) => {
  const getStatusColor = (status: ApplicationStatus) => {
    switch (status) {
      case ApplicationStatus.APPROVED: return 'bg-emerald-100 text-emerald-700 border-emerald-200';
      case ApplicationStatus.REJECTED: return 'bg-rose-100 text-rose-700 border-rose-200';
      case ApplicationStatus.HOD_PENDING: return 'bg-amber-100 text-amber-700 border-amber-200';
      case ApplicationStatus.DIRECTOR_PENDING: return 'bg-blue-100 text-blue-700 border-blue-200';
      default: return 'bg-slate-100 text-slate-700 border-slate-200';
    }
  };

  return (
    <div 
      onClick={onClick}
      className={`p-5 rounded-xl border transition-all cursor-pointer ${
        isActive 
          ? 'bg-indigo-50 border-indigo-200 shadow-md ring-1 ring-indigo-500' 
          : 'bg-white border-slate-200 hover:border-indigo-300 hover:shadow-sm'
      }`}
    >
      <div className="flex justify-between items-start mb-3">
        <span className={`px-2.5 py-0.5 rounded-full text-[10px] font-bold uppercase border ${getStatusColor(app.status)}`}>
          {app.status.replace('_', ' ')}
        </span>
        <span className="text-[10px] font-medium text-slate-400">
          ID: {app.id.slice(0, 8)}
        </span>
      </div>
      <h4 className="font-bold text-slate-800 line-clamp-1">{app.researchTitle}</h4>
      <p className="text-sm text-slate-500 mt-1">{app.applicantName}</p>

      <div className="mt-4 flex items-center justify-between">
        <div className="flex -space-x-2">
          {app.teamMembers.slice(0, 3).map((m, i) => (
            <div key={i} className="w-6 h-6 rounded-full bg-indigo-100 border-2 border-white flex items-center justify-center text-[10px] font-bold text-indigo-600">
              {m.name.charAt(0)}
            </div>
          ))}
          {app.teamMembers.length > 3 && (
            <div className="w-6 h-6 rounded-full bg-slate-100 border-2 border-white flex items-center justify-center text-[10px] font-bold text-slate-600">
              +{app.teamMembers.length - 3}
            </div>
          )}
        </div>
        <div className="text-[11px] font-medium text-slate-400 italic">
          {new Date(app.submissionDate).toLocaleDateString()}
        </div>
      </div>
    </div>
  );
};

export default ApplicationCard;

import React, { useState } from 'react';
import { Application, ApplicationStatus, TeamMember, REVIEWER_LIST } from '../types';

interface ApplicationWizardProps {
  onCancel: () => void;
  onSubmit: (app: Application) => void;
}

const ApplicationWizard: React.FC<ApplicationWizardProps> = ({ onCancel, onSubmit }) => {
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState({
    applicantName: '',
    applicantIdCard: '',
    applicantEmail: '',
    applicantPhone: '',
    teamName: '',
    researchTitle: '',
    researchLink: '',
    eventName: '',
    eventLocation: '',
    eventDate: '',
    eventLevel: 'National' as 'National' | 'International',
    teamMembers: [] as TeamMember[],
    selectedReviewers: [] as string[]
  });

  const [newMember, setNewMember] = useState<TeamMember>({ name: '', position: '', idCard: '' });

  const addTeamMember = () => {
    if (newMember.name && newMember.idCard) {
      setFormData(prev => ({ ...prev, teamMembers: [...prev.teamMembers, newMember] }));
      setNewMember({ name: '', position: '', idCard: '' });
    }
  };

  const toggleReviewer = (reviewer: string) => {
    setFormData(prev => {
      const exists = prev.selectedReviewers.includes(reviewer);
      if (exists) return { ...prev, selectedReviewers: prev.selectedReviewers.filter(r => r !== reviewer) };
      if (prev.selectedReviewers.length >= 3) return prev;
      return { ...prev, selectedReviewers: [...prev.selectedReviewers, reviewer] };
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.selectedReviewers.length < 3) {
      alert("Please select exactly 3 reviewers.");
      return;
    }
    const app: Application = {
      ...formData,
      id: Math.random().toString(36).substr(2, 9),
      submissionDate: new Date().toISOString(),
      status: ApplicationStatus.SUBMITTED,
      reviews: {},
      hodStatus: null,
      hodComments: '',
      hodDate: null,
      directorStatus: null,
      directorComments: '',
      directorDate: null,
    };
    onSubmit(app);
  };

  return (
    <div className="max-w-3xl mx-auto bg-white rounded-2xl border border-slate-200 shadow-lg overflow-hidden">
      <div className="bg-indigo-600 p-8 text-white">
        <h2 className="text-2xl font-bold">New Research Application</h2>
        <p className="text-indigo-100 text-sm mt-1">Fill out the following details to submit your research for approval.</p>

        <div className="flex gap-2 mt-6">
          {[1, 2, 3, 4].map(s => (
            <div key={s} className={`h-1 flex-1 rounded-full ${s <= step ? 'bg-white' : 'bg-indigo-400'}`}></div>
          ))}
        </div>
      </div>

      <form onSubmit={handleSubmit} className="p-8 space-y-6">
        {step === 1 && (
          <div className="space-y-4 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <h3 className="font-bold text-slate-800 border-b pb-2">Step 1: Applicant Information</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Full Name</label>
                <input required value={formData.applicantName} onChange={e => setFormData({...formData, applicantName: e.target.value})} className="w-full border border-slate-200 rounded-lg p-2.5 focus:ring-2 focus:ring-indigo-500 outline-none" />
              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Identity Card Number</label>
                <input required value={formData.applicantIdCard} onChange={e => setFormData({...formData, applicantIdCard: e.target.value})} className="w-full border border-slate-200 rounded-lg p-2.5 focus:ring-2 focus:ring-indigo-500 outline-none" />
              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Official Email</label>
                <input required type="email" value={formData.applicantEmail} onChange={e => setFormData({...formData, applicantEmail: e.target.value})} className="w-full border border-slate-200 rounded-lg p-2.5 focus:ring-2 focus:ring-indigo-500 outline-none" />
              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Phone Number</label>
                <input required value={formData.applicantPhone} onChange={e => setFormData({...formData, applicantPhone: e.target.value})} className="w-full border border-slate-200 rounded-lg p-2.5 focus:ring-2 focus:ring-indigo-500 outline-none" />
              </div>
            </div>
          </div>
        )}

        {step === 2 && (
          <div className="space-y-4 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <h3 className="font-bold text-slate-800 border-b pb-2">Step 2: Team Members</h3>
            <div className="space-y-1">
              <label className="text-xs font-bold text-slate-500 uppercase">Team Name</label>
              <input value={formData.teamName} onChange={e => setFormData({...formData, teamName: e.target.value})} className="w-full border border-slate-200 rounded-lg p-2.5 focus:ring-2 focus:ring-indigo-500 outline-none" />
            </div>

            <div className="bg-slate-50 p-4 rounded-xl space-y-3">
              <h4 className="text-sm font-bold text-slate-600">Add Team Member</h4>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                <input placeholder="Name" value={newMember.name} onChange={e => setNewMember({...newMember, name: e.target.value})} className="text-sm border border-slate-200 rounded p-2" />
                <input placeholder="Position" value={newMember.position} onChange={e => setNewMember({...newMember, position: e.target.value})} className="text-sm border border-slate-200 rounded p-2" />
                <input placeholder="ID Card" value={newMember.idCard} onChange={e => setNewMember({...newMember, idCard: e.target.value})} className="text-sm border border-slate-200 rounded p-2" />
              </div>
              <button type="button" onClick={addTeamMember} className="w-full bg-slate-200 hover:bg-slate-300 text-slate-700 py-1.5 rounded-lg text-xs font-bold transition-all">
                ADD MEMBER
              </button>
            </div>

            <div className="space-y-2">
              {formData.teamMembers.map((m, i) => (
                <div key={i} className="flex justify-between items-center bg-white border border-slate-100 p-3 rounded-lg shadow-sm">
                  <div>
                    <p className="text-sm font-bold">{m.name}</p>
                    <p className="text-xs text-slate-500">{m.position} • {m.idCard}</p>
                  </div>
                  <button type="button" onClick={() => setFormData({...formData, teamMembers: formData.teamMembers.filter((_, idx) => idx !== i)})} className="text-rose-500 hover:text-rose-700">
                    <i className="fas fa-trash-alt text-sm"></i>
                  </button>
                </div>
              ))}
            </div>
          </div>
        )}

        {step === 3 && (
          <div className="space-y-4 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <h3 className="font-bold text-slate-800 border-b pb-2">Step 3: Research & Event</h3>
            <div className="space-y-4">
              <div className="space-y-1">
