import React, { useState } from 'react';
import { Application, ApplicationStatus, TeamMember, REVIEWER_LIST } from '../types';

interface ApplicationWizardProps {
  onCancel: () => void;
  onSubmit: (app: Application) => void;
}

const ApplicationWizard: React.FC<ApplicationWizardProps> = ({ onCancel, onSubmit }) => {
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState({
    applicantName: '',
    applicantIdCard: '',
    applicantEmail: '',
    applicantPhone: '',
    teamName: '',
    researchTitle: '',
    researchLink: '',
    eventName: '',
    eventLocation: '',
    eventDate: '',
    eventLevel: 'National' as 'National' | 'International',
    teamMembers: [] as TeamMember[],
    selectedReviewers: [] as string[]
  });

  const [newMember, setNewMember] = useState<TeamMember>({ name: '', position: '', idCard: '' });

  const addTeamMember = () => {
    if (newMember.name && newMember.idCard) {
      setFormData(prev => ({ ...prev, teamMembers: [...prev.teamMembers, newMember] }));
      setNewMember({ name: '', position: '', idCard: '' });
    }
  };

  const toggleReviewer = (reviewer: string) => {
    setFormData(prev => {
      // Changed to only allow one reviewer selection
      const exists = prev.selectedReviewers.includes(reviewer);
      if (exists) return { ...prev, selectedReviewers: [] };
      return { ...prev, selectedReviewers: [reviewer] };
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.selectedReviewers.length !== 1) {
      alert("Please select exactly 1 reviewer.");
      return;
    }
    const app: Application = {
      ...formData,
      id: Math.random().toString(36).substr(2, 9),
      submissionDate: new Date().toISOString(),
      status: ApplicationStatus.SUBMITTED,
      reviews: {},
      hodStatus: null,
      hodComments: '',
      hodDate: null,
      directorStatus: null,
      directorComments: '',
      directorDate: null,
    };
    onSubmit(app);
  };

  return (
    <div className="max-w-3xl mx-auto bg-white rounded-2xl border border-slate-200 shadow-lg overflow-hidden">
      <div className="bg-indigo-600 p-8 text-white">
        <h2 className="text-2xl font-bold">New Research Application</h2>
        <p className="text-indigo-100 text-sm mt-1">Fill out the following details to submit your research for approval.</p>

        <div className="flex gap-2 mt-6">
          {[1, 2, 3, 4].map(s => (
            <div key={s} className={`h-1 flex-1 rounded-full ${s <= step ? 'bg-white' : 'bg-indigo-400'}`}></div>
          ))}
        </div>
      </div>

      <form onSubmit={handleSubmit} className="p-8 space-y-6">
        {step === 1 && (
          <div className="space-y-4 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <h3 className="font-bold text-slate-800 border-b pb-2">Step 1: Applicant Information</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Full Name</label>
                <input required value={formData.applicantName} onChange={e => setFormData({...formData, applicantName: e.target.value})} className="w-full border border-slate-200 rounded-lg p-2.5 focus:ring-2 focus:ring-indigo-500 outline-none" />
              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Identity Card Number</label>
                <input required value={formData.applicantIdCard} onChange={e => setFormData({...formData, applicantIdCard: e.target.value})} className="w-full border border-slate-200 rounded-lg p-2.5 focus:ring-2 focus:ring-indigo-500 outline-none" />
              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Official Email</label>
                <input required type="email" value={formData.applicantEmail} onChange={e => setFormData({...formData, applicantEmail: e.target.value})} className="w-full border border-slate-200 rounded-lg p-2.5 focus:ring-2 focus:ring-indigo-500 outline-none" />
              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Phone Number</label>
                <input required value={formData.applicantPhone} onChange={e => setFormData({...formData, applicantPhone: e.target.value})} className="w-full border border-slate-200 rounded-lg p-2.5 focus:ring-2 focus:ring-indigo-500 outline-none" />
              </div>
            </div>
          </div>
        )}

        {step === 2 && (
          <div className="space-y-4 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <h3 className="font-bold text-slate-800 border-b pb-2">Step 2: Team Members</h3>
            <div className="space-y-1">
              <label className="text-xs font-bold text-slate-500 uppercase">Team Name</label>
              <input value={formData.teamName} onChange={e => setFormData({...formData, teamName: e.target.value})} className="w-full border border-slate-200 rounded-lg p-2.5 focus:ring-2 focus:ring-indigo-500 outline-none" />
            </div>

            <div className="bg-slate-50 p-4 rounded-xl space-y-3">
              <h4 className="text-sm font-bold text-slate-600">Add Team Member</h4>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                <input placeholder="Name" value={newMember.name} onChange={e => setNewMember({...newMember, name: e.target.value})} className="text-sm border border-slate-200 rounded p-2" />
                <input placeholder="Position" value={newMember.position} onChange={e => setNewMember({...newMember, position: e.target.value})} className="text-sm border border-slate-200 rounded p-2" />
                <input placeholder="ID Card" value={newMember.idCard} onChange={e => setNewMember({...newMember, idCard: e.target.value})} className="text-sm border border-slate-200 rounded p-2" />
              </div>
              <button type="button" onClick={addTeamMember} className="w-full bg-slate-200 hover:bg-slate-300 text-slate-700 py-1.5 rounded-lg text-xs font-bold transition-all">
                ADD MEMBER
              </button>
            </div>

            <div className="space-y-2">
              {formData.teamMembers.map((m, i) => (
                <div key={i} className="flex justify-between items-center bg-white border border-slate-100 p-3 rounded-lg shadow-sm">
                  <div>
                    <p className="text-sm font-bold">{m.name}</p>
                    <p className="text-xs text-slate-500">{m.position} • {m.idCard}</p>
                  </div>
                  <button type="button" onClick={() => setFormData({...formData, teamMembers: formData.teamMembers.filter((_, idx) => idx !== i)})} className="text-rose-500 hover:text-rose-700">
                    <i className="fas fa-trash-alt text-sm"></i>
                  </button>
                </div>
              ))}
            </div>
          </div>
        )}

        {step === 3 && (
          <div className="space-y-4 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <h3 className="font-bold text-slate-800 border-b pb-2">Step 3: Research & Event</h3>
            <div className="space-y-4">
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Research Title</label>
                <input required value={formData.researchTitle} onChange={e => setFormData({...formData, researchTitle: e.target.value})} className="w-full border border-slate-200 rounded-lg p-2.5 focus:ring-2 focus:ring-indigo-500 outline-none" />
              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Online Paper Link</label>
                <input required type="url" value={formData.researchLink} onChange={e => setFormData({...formData, researchLink: e.target.value})} className="w-full border border-slate-200 rounded-lg p-2.5 focus:ring-2 focus:ring-indigo-500 outline-none" placeholder="https://..." />
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4 pt-2">
                <div className="space-y-1">
                  <label className="text-xs font-bold text-slate-500 uppercase">Event Name</label>
                  <input required value={formData.eventName} onChange={e => setFormData({...formData, eventName: e.target.value})} className="w-full border border-slate-200 rounded-lg p-2.5 focus:ring-2 focus:ring-indigo-500 outline-none" />
                </div>
                <div className="space-y-1">
                  <label className="text-xs font-bold text-slate-500 uppercase">Location</label>
                  <input required value={formData.eventLocation} onChange={e => setFormData({...formData, eventLocation: e.target.value})} className="w-full border border-slate-200 rounded-lg p-2.5 focus:ring-2 focus:ring-indigo-500 outline-none" />
                </div>
                <div className="space-y-1">
                  <label className="text-xs font-bold text-slate-500 uppercase">Event Date</label>
                  <input required type="date" value={formData.eventDate} onChange={e => setFormData({...formData, eventDate: e.target.value})} className="w-full border border-slate-200 rounded-lg p-2.5 focus:ring-2 focus:ring-indigo-500 outline-none" />
                </div>
                <div className="space-y-1">
                  <label className="text-xs font-bold text-slate-500 uppercase">Level</label>
                  <select value={formData.eventLevel} onChange={e => setFormData({...formData, eventLevel: e.target.value as any})} className="w-full border border-slate-200 rounded-lg p-2.5 focus:ring-2 focus:ring-indigo-500 outline-none bg-white">
                    <option value="National">National</option>
                    <option value="International">International</option>
                  </select>
                </div>
              </div>
            </div>
          </div>
        )}

        {step === 4 && (
          <div className="space-y-4 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <h3 className="font-bold text-slate-800 border-b pb-2">Step 4: Select a Reviewer</h3>
            <p className="text-sm text-slate-500">Choose an expert who will review your research paper.</p>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              {REVIEWER_LIST.map(r => (
                <div 
                  key={r} 
                  onClick={() => toggleReviewer(r)}
                  className={`flex items-center gap-3 p-4 rounded-xl border-2 transition-all cursor-pointer ${
                    formData.selectedReviewers.includes(r) 
                      ? 'border-indigo-600 bg-indigo-50 ring-1 ring-indigo-600' 
                      : 'border-slate-100 bg-white hover:border-slate-200'
                  }`}
                >
                  <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center ${formData.selectedReviewers.includes(r) ? 'bg-indigo-600 border-indigo-600' : 'border-slate-300'}`}>
                    {formData.selectedReviewers.includes(r) && <i className="fas fa-check text-[10px] text-white"></i>}
                  </div>
                  <span className="text-sm font-semibold text-slate-700">{r}</span>
                </div>
              ))}
            </div>
            <div className="mt-4 p-4 bg-slate-50 rounded-lg">
              <p className="text-xs font-bold text-slate-500 uppercase">Selected ({formData.selectedReviewers.length}/1)</p>
              <div className="flex flex-wrap gap-2 mt-2">
                {formData.selectedReviewers.map(r => (
                  <span key={r} className="bg-indigo-100 text-indigo-700 px-3 py-1 rounded-full text-xs font-bold">{r}</span>
                ))}
                {formData.selectedReviewers.length === 0 && <span className="text-slate-400 text-xs italic">No reviewer selected</span>}
              </div>
            </div>
          </div>
        )}

        {/* Navigation */}
        <div className="flex justify-between pt-8 mt-4 border-t border-slate-100">
          <button type="button" onClick={step === 1 ? onCancel : () => setStep(step - 1)} className="px-6 py-2.5 rounded-lg font-bold text-slate-600 hover:bg-slate-100 transition-all">
            {step === 1 ? 'CANCEL' : 'BACK'}
          </button>

          {step < 4 ? (
            <button type="button" onClick={() => setStep(step + 1)} className="bg-indigo-600 hover:bg-indigo-700 text-white px-8 py-2.5 rounded-lg font-bold shadow-sm transition-all">
              CONTINUE
            </button>
          ) : (
            <button type="submit" className="bg-emerald-600 hover:bg-emerald-700 text-white px-8 py-2.5 rounded-lg font-bold shadow-md transition-all">
              SUBMIT APPLICATION
            </button>
          )}
        </div>
      </form>
    </div>
  );
};

export default ApplicationWizard;

import React, { useState } from 'react';
import { UserRole, Application, ApplicationStatus, ReviewRating, ReviewData } from '../types';
import { suggestResearchImprovements } from '../services/geminiService';

interface StageActionsProps {
  role: UserRole;
  app: Application;
  onUpdate: (app: Application) => void;
}

const StageActions: React.FC<StageActionsProps> = ({ role, app, onUpdate }) => {
  const [comment, setComment] = useState('');
  const [rating, setRating] = useState<ReviewRating>(ReviewRating.GOOD);
  const [isAiLoading, setIsAiLoading] = useState(false);

  // --- Reviewer Stage ---
  const handleReviewerSubmit = () => {
    const updatedReviews = { ...app.reviews };
    updatedReviews[role] = {
      reviewerId: role,
      comments: comment,
      status: rating,
      date: new Date().toISOString()
    };

    let nextStatus = app.status;
    // Changed to proceed to HOD stage after 1 review instead of 3
    if (Object.keys(updatedReviews).length >= 1) {
      nextStatus = ApplicationStatus.HOD_PENDING;
    }

    onUpdate({
      ...app,
      reviews: updatedReviews,
      status: nextStatus
    });
    setComment('');
  };

  const useGeminiAssistant = async () => {
    setIsAiLoading(true);
    const suggestions = await suggestResearchImprovements(app.researchTitle, app.researchLink);
    setComment(prev => (prev ? prev + "\n\n" : "") + "AI Suggested Improvements:\n" + suggestions);
    setIsAiLoading(false);
  };

  // --- HOD Stage ---
  const handleHODDecision = (decision: 'Supported' | 'Unsupported') => {
    onUpdate({
      ...app,
      hodStatus: decision,
      hodComments: comment,
      hodDate: new Date().toISOString(),
      status: decision === 'Supported' ? ApplicationStatus.DIRECTOR_PENDING : ApplicationStatus.REJECTED
    });
    setComment('');
  };

  // --- Director Stage ---
  const handleDirectorDecision = (decision: 'Approved' | 'Unapproved') => {
    onUpdate({
      ...app,
      directorStatus: decision,
      directorComments: comment,
      directorDate: new Date().toISOString(),
      status: decision === 'Approved' ? ApplicationStatus.APPROVED : ApplicationStatus.REJECTED
    });
    setComment('');
  };

  // Check if current reviewer already reviewed
  const hasReviewed = app.reviews[role];

  if (role === UserRole.APPLICANT) {
    return (
      <div className="text-center py-6">
        <i className="fas fa-hourglass-half text-indigo-400 text-3xl mb-3"></i>
        <h4 className="font-bold text-slate-800">Application Tracked</h4>
        <p className="text-sm text-slate-500 max-w-sm mx-auto mt-2">
          Your application is currently being processed. You will be notified of any status updates or feedback requirements.
        </p>
      </div>
    );
  }

  // Reviewer View
  if (role.startsWith('REVIEWER')) {
    if (hasReviewed) {
      return (
        <div className="bg-emerald-50 border border-emerald-100 p-4 rounded-xl">
          <p className="text-sm font-bold text-emerald-700 flex items-center gap-2">
            <i className="fas fa-check-circle"></i> Review Completed
          </p>
          <div className="mt-3 text-xs space-y-1">
            <p><span className="font-bold">Rating:</span> {hasReviewed.status}</p>
            <p><span className="font-bold">Date:</span> {new Date(hasReviewed.date).toLocaleString()}</p>
            <p className="mt-2 text-slate-600 bg-white p-3 rounded-lg border border-emerald-100 italic">"{hasReviewed.comments}"</p>
          </div>
        </div>
      );
    }

    return (
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <h4 className="font-bold text-slate-800">Review Submission</h4>
          <button 
            onClick={useGeminiAssistant}
            disabled={isAiLoading}
            className="text-xs font-bold flex items-center gap-2 bg-gradient-to-r from-indigo-500 to-purple-500 text-white px-3 py-1.5 rounded-full hover:shadow-lg disabled:opacity-50 transition-all"
          >
            <i className={`fas ${isAiLoading ? 'fa-spinner fa-spin' : 'fa-magic'}`}></i>
            {isAiLoading ? 'Analyzing...' : 'AI ASSISTANT'}
          </button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
          {Object.values(ReviewRating).map(r => (
            <button 
              key={r}
              onClick={() => setRating(r)}
              className={`py-2 text-xs font-bold rounded-lg border-2 transition-all ${rating === r ? 'bg-indigo-600 text-white border-indigo-600 shadow-md' : 'bg-white text-slate-600 border-slate-200'}`}
            >
              {r.toUpperCase()}
            </button>
          ))}
        </div>

        <textarea 
          placeholder="Write your comments on what to improve..."
          value={comment}
          onChange={e => setComment(e.target.value)}
          className="w-full border border-slate-200 rounded-xl p-4 text-sm focus:ring-2 focus:ring-indigo-500 outline-none h-32"
        />

        <button 
          onClick={handleReviewerSubmit}
          disabled={!comment}
          className="w-full bg-slate-800 hover:bg-slate-900 text-white font-bold py-3 rounded-xl disabled:opacity-50 transition-all shadow-lg"
        >
          SUBMIT REVIEW
        </button>
      </div>
    );
  }

  // HOD View
  if (role === UserRole.HOD) {
    return (
      <div className="space-y-4">
        <h4 className="font-bold text-slate-800">Head of Department Action</h4>
        <div className="bg-white p-4 rounded-xl border border-slate-200 mb-4">
          <h5 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-3">Review Feedback</h5>
          <div className="space-y-3">
            {(Object.entries(app.reviews) as [string, ReviewData][]).map(([key, rev]) => (
              <div key={key} className="text-xs pb-2 border-b border-slate-50 last:border-0">
                <div className="flex justify-between items-center mb-1">
                  <span className="font-bold text-slate-700">{key.replace('_', ' ')}</span>
                  <span className={`px-2 py-0.5 rounded-full text-[9px] font-bold ${rev.status === ReviewRating.EXCELLENT ? 'bg-emerald-100 text-emerald-700' : rev.status === ReviewRating.GOOD ? 'bg-indigo-100 text-indigo-700' : 'bg-rose-100 text-rose-700'}`}>
                    {rev.status}
                  </span>
                </div>
                <p className="text-slate-500 italic">"{rev.comments}"</p>
              </div>
            ))}
            {Object.keys(app.reviews).length === 0 && <p className="text-xs text-slate-400 italic">No reviews found.</p>}
          </div>
        </div>

        <textarea 
          placeholder="Remarks or comments..."
          value={comment}
          onChange={e => setComment(e.target.value)}
          className="w-full border border-slate-200 rounded-xl p-4 text-sm focus:ring-2 focus:ring-indigo-500 outline-none h-32"
        />

        <div className="grid grid-cols-2 gap-4">
          <button 
            onClick={() => handleHODDecision('Unsupported')}
            className="bg-white border-2 border-rose-200 text-rose-600 hover:bg-rose-50 font-bold py-3 rounded-xl transition-all"
          >
            UNSUPPORTED
          </button>
          <button 
            onClick={() => handleHODDecision('Supported')}
            className="bg-emerald-600 hover:bg-emerald-700 text-white font-bold py-3 rounded-xl shadow-lg transition-all"
          >
            SUPPORTED
          </button>
        </div>
      </div>
    );
  }

  // Director View
  if (role === UserRole.DIRECTOR) {
    return (
      <div className="space-y-4">
        <h4 className="font-bold text-slate-800">Director Final Approval</h4>
        <div className="bg-indigo-50 p-4 rounded-xl border border-indigo-100">
          <h5 className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest mb-1">HOD Recommendation</h5>
          <p className="text-xs font-semibold text-slate-700">Status: <span className="text-emerald-600">{app.hodStatus}</span></p>
          <p className="text-xs text-slate-500 mt-1 italic">"{app.hodComments}"</p>
        </div>

        <textarea 
          placeholder="Final remarks for approval/rejection..."
          value={comment}
          onChange={e => setComment(e.target.value)}
          className="w-full border border-slate-200 rounded-xl p-4 text-sm focus:ring-2 focus:ring-indigo-500 outline-none h-32"
        />

        <div className="grid grid-cols-2 gap-4">
          <button 
            onClick={() => handleDirectorDecision('Unapproved')}
            className="bg-white border-2 border-slate-200 text-slate-500 hover:bg-slate-50 font-bold py-3 rounded-xl transition-all"
          >
            UNAPPROVE
          </button>
          <button 
            onClick={() => handleDirectorDecision('Approved')}
            className="bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 rounded-xl shadow-lg transition-all"
          >
            APPROVE
          </button>
        </div>
      </div>
    );
  }

  return null;
};

export default StageActions;

import React, { useState } from 'react';
import { UserRole, Application, ApplicationStatus, ReviewData } from '../types';
import ApplicationCard from './ApplicationCard';
import StageActions from './StageActions';

interface DashboardProps {
  role: UserRole;
  applications: Application[];
  onCreateNew: () => void;
  onUpdateApplication: (app: Application) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ role, applications, onCreateNew, onUpdateApplication }) => {
  const [selectedApp, setSelectedApp] = useState<Application | null>(null);

  // Filter logic based on requirements: "each stage can only be seen by respective people"
  const filteredApps = applications.filter(app => {
    if (role === UserRole.APPLICANT) return true; // See all your own

    if (role === UserRole.REVIEWER_1 || role === UserRole.REVIEWER_2 || role === UserRole.REVIEWER_3) {
      // Must be in reviewer list and application must be submitted/under review
      return app.status === ApplicationStatus.SUBMITTED || app.status === ApplicationStatus.UNDER_REVIEW;
    }

    if (role === UserRole.HOD) {
      // Must have reviews completed
      return app.status === ApplicationStatus.HOD_PENDING;
    }

    if (role === UserRole.DIRECTOR) {
      // Must be supported by HOD
      return app.status === ApplicationStatus.DIRECTOR_PENDING;
    }

    return false;
  });

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">
            {role === UserRole.APPLICANT ? 'My Applications' : 'Pending Tasks'}
          </h2>
          <p className="text-slate-500">Manage research paper submission and approval cycles.</p>
        </div>
        {role === UserRole.APPLICANT && (
          <button 
            onClick={onCreateNew}
            className="flex items-center justify-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white px-5 py-2.5 rounded-lg font-semibold shadow-sm transition-all"
          >
            <i className="fas fa-plus"></i>
