                    const isDone = 
                      (idx === 0) || 
                      (idx === 1 && Object.keys(selectedApp.reviews).length >= 1) || // Updated for single reviewer
                      (idx === 2 && selectedApp.hodStatus === 'Supported') ||
                      (idx === 3 && selectedApp.directorStatus === 'Approved');

                    return (
                      <div key={step} className="flex flex-col items-center gap-2 relative z-10">
                        <div className={`w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold transition-colors ${isDone ? 'bg-indigo-600 text-white' : 'bg-white border-2 border-slate-200 text-slate-400'}`}>
