import React, { useState } from 'react';
import { UserRole, Application, ApplicationStatus, ReviewRating, ReviewData, REVIEWER_LIST } from '../types';
import { suggestResearchImprovements } from '../services/geminiService';

interface StageActionsProps {
  role: UserRole;
  app: Application;
  onUpdate: (app: Application) => void;
}

const StageActions: React.FC<StageActionsProps> = ({ role, app, onUpdate }) => {
  const [comment, setComment] = useState('');
  const [rating, setRating] = useState<ReviewRating>(ReviewRating.GOOD);
  const [isAiLoading, setIsAiLoading] = useState(false);

  // --- Reviewer Stage ---
  const handleReviewerSubmit = () => {
    const updatedReviews = { ...app.reviews };
    updatedReviews[role] = {
      reviewerId: role,
      comments: comment,
      status: rating,
      date: new Date().toISOString()
    };

    let nextStatus = app.status;
    if (Object.keys(updatedReviews).length >= 1) {
      nextStatus = ApplicationStatus.HOD_PENDING;
    }

    onUpdate({
      ...app,
      reviews: updatedReviews,
      status: nextStatus
    });
    setComment('');
  };

  const useGeminiAssistant = async () => {
    setIsAiLoading(true);
    const suggestions = await suggestResearchImprovements(app.researchTitle, app.researchLink);
    setComment(prev => (prev ? prev + "\n\n" : "") + "AI Suggested Improvements:\n" + suggestions);
    setIsAiLoading(false);
  };

  // --- HOD Stage ---
  const handleHODDecision = (decision: 'Supported' | 'Unsupported') => {
    onUpdate({
      ...app,
      hodStatus: decision,
      hodComments: comment,
      hodDate: new Date().toISOString(),
      status: decision === 'Supported' ? ApplicationStatus.DIRECTOR_PENDING : ApplicationStatus.REJECTED
    });
    setComment('');
  };

  // --- Director Stage ---
  const handleDirectorDecision = (decision: 'Approved' | 'Unapproved') => {
    onUpdate({
      ...app,
      directorStatus: decision,
      directorComments: comment,
      directorDate: new Date().toISOString(),
      status: decision === 'Approved' ? ApplicationStatus.APPROVED : ApplicationStatus.REJECTED
    });
    setComment('');
  };

  // Check if current reviewer already reviewed
  const hasReviewed = app.reviews[role];

  if (role === UserRole.APPLICANT) {
    return (
      <div className="text-center py-6">
        <i className="fas fa-hourglass-half text-indigo-400 text-3xl mb-3"></i>
        <h4 className="font-bold text-slate-800">Application Tracked</h4>
        <p className="text-sm text-slate-500 max-w-sm mx-auto mt-2">
          Your application is currently being processed. You will be notified of any status updates or feedback requirements.
        </p>
      </div>
    );
  }

  // Reviewer View
  if (REVIEWER_LIST.includes(role)) {
    if (hasReviewed) {
      return (
        <div className="bg-emerald-50 border border-emerald-100 p-4 rounded-xl">
          <p className="text-sm font-bold text-emerald-700 flex items-center gap-2">
            <i className="fas fa-check-circle"></i> Review Completed
          </p>
          <div className="mt-3 text-xs space-y-1">
            <p><span className="font-bold">Rating:</span> {hasReviewed.status}</p>
            <p><span className="font-bold">Date:</span> {new Date(hasReviewed.date).toLocaleString()}</p>
            <p className="mt-2 text-slate-600 bg-white p-3 rounded-lg border border-emerald-100 italic">"{hasReviewed.comments}"</p>
          </div>
        </div>
      );
    }

    return (
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <h4 className="font-bold text-slate-800">Review Submission</h4>
          <button 
            onClick={useGeminiAssistant}
            disabled={isAiLoading}
            className="text-xs font-bold flex items-center gap-2 bg-gradient-to-r from-indigo-500 to-purple-500 text-white px-3 py-1.5 rounded-full hover:shadow-lg disabled:opacity-50 transition-all"
          >
            <i className={`fas ${isAiLoading ? 'fa-spinner fa-spin' : 'fa-magic'}`}></i>
            {isAiLoading ? 'Analyzing...' : 'AI ASSISTANT'}
          </button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
          {Object.values(ReviewRating).map(r => (
            <button 
              key={r}
              onClick={() => setRating(r)}
              className={`py-2 text-xs font-bold rounded-lg border-2 transition-all ${rating === r ? 'bg-indigo-600 text-white border-indigo-600 shadow-md' : 'bg-white text-slate-600 border-slate-200'}`}
            >
              {r.toUpperCase()}
            </button>
          ))}
        </div>

        <textarea 
          placeholder="Write your comments on what to improve..."
          value={comment}
          onChange={e => setComment(e.target.value)}
          className="w-full border border-slate-200 rounded-xl p-4 text-sm focus:ring-2 focus:ring-indigo-500 outline-none h-32"
        />

        <button 
          onClick={handleReviewerSubmit}
          disabled={!comment}
          className="w-full bg-slate-800 hover:bg-slate-900 text-white font-bold py-3 rounded-xl disabled:opacity-50 transition-all shadow-lg"
        >
          SUBMIT REVIEW
        </button>
      </div>
    );
  }

  // HOD View
  if (role === UserRole.HOD) {
    return (
      <div className="space-y-4">
        <h4 className="font-bold text-slate-800">Head of Department Action</h4>
        <div className="bg-white p-4 rounded-xl border border-slate-200 mb-4">
          <h5 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-3">Review Feedback</h5>
          <div className="space-y-3">
            {(Object.entries(app.reviews) as [string, ReviewData][]).map(([key, rev]) => (
              <div key={key} className="text-xs pb-2 border-b border-slate-50 last:border-0">
                <div className="flex justify-between items-center mb-1">
                  <span className="font-bold text-slate-700">{key}</span>
                  <span className={`px-2 py-0.5 rounded-full text-[9px] font-bold ${rev.status === ReviewRating.EXCELLENT ? 'bg-emerald-100 text-emerald-700' : rev.status === ReviewRating.GOOD ? 'bg-indigo-100 text-indigo-700' : 'bg-rose-100 text-rose-700'}`}>
                    {rev.status}
                  </span>
                </div>
                <p className="text-slate-500 italic">"{rev.comments}"</p>
              </div>
            ))}
            {Object.keys(app.reviews).length === 0 && <p className="text-xs text-slate-400 italic">No reviews found.</p>}
          </div>
        </div>

        <textarea 
          placeholder="Remarks or comments..."
          value={comment}
          onChange={e => setComment(e.target.value)}
          className="w-full border border-slate-200 rounded-xl p-4 text-sm focus:ring-2 focus:ring-indigo-500 outline-none h-32"
        />

        <div className="grid grid-cols-2 gap-4">
          <button 
            onClick={() => handleHODDecision('Unsupported')}
            className="bg-white border-2 border-rose-200 text-rose-600 hover:bg-rose-50 font-bold py-3 rounded-xl transition-all"
          >
            UNSUPPORTED
          </button>
          <button 
            onClick={() => handleHODDecision('Supported')}
            className="bg-emerald-600 hover:bg-emerald-700 text-white font-bold py-3 rounded-xl shadow-lg transition-all"
          >
            SUPPORTED
          </button>
        </div>
      </div>
    );
  }

  // Director View
  if (role === UserRole.DIRECTOR) {
    return (
      <div className="space-y-4">
        <h4 className="font-bold text-slate-800">Director Final Approval</h4>
        <div className="bg-indigo-50 p-4 rounded-xl border border-indigo-100">
          <h5 className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest mb-1">HOD Recommendation</h5>
          <p className="text-xs font-semibold text-slate-700">Status: <span className="text-emerald-600">{app.hodStatus}</span></p>
          <p className="text-xs text-slate-500 mt-1 italic">"{app.hodComments}"</p>
        </div>

        <textarea 
          placeholder="Final remarks for approval/rejection..."
          value={comment}
          onChange={e => setComment(e.target.value)}
          className="w-full border border-slate-200 rounded-xl p-4 text-sm focus:ring-2 focus:ring-indigo-500 outline-none h-32"
        />

        <div className="grid grid-cols-2 gap-4">
          <button 
            onClick={() => handleDirectorDecision('Unapproved')}
            className="bg-white border-2 border-slate-200 text-slate-500 hover:bg-slate-50 font-bold py-3 rounded-xl transition-all"
          >
            UNAPPROVE
          </button>
          <button 
            onClick={() => handleDirectorDecision('Approved')}
            className="bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 rounded-xl shadow-lg transition-all"
          >
            APPROVE
          </button>
        </div>
      </div>
    );
  }

  return null;
};

export default StageActions;

payload.text:
To transition your app to use Google Sheets as a database, we will use **Google Apps Script** as a middleman. 

First, you need to set up the spreadsheet. Please follow these steps:
1. Create a new **Google Sheet**.
2. Go to **Extensions** > **Apps Script**.
3. Delete any code there and paste the following:

```javascript
const SHEET_NAME = "Applications";

function doGet() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_NAME) || SpreadsheetApp.getActiveSpreadsheet().insertSheet(SHEET_NAME);
  const data = sheet.getDataRange().getValues();
  if (data.length <= 1) return ContentService.createTextOutput("[]").setMimeType(ContentService.MimeType.JSON);

  const apps = data.slice(1).map(row => JSON.parse(row[1]));
  return ContentService.createTextOutput(JSON.stringify(apps)).setMimeType(ContentService.MimeType.JSON);
}

function doPost(e) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_NAME) || SpreadsheetApp.getActiveSpreadsheet().insertSheet(SHEET_NAME);
  const appData = JSON.parse(e.postData.contents);
  const data = sheet.getDataRange().getValues();

  let rowIndex = -1;
  for (let i = 1; i < data.length; i++) {
    if (data[i][0] === appData.id) { rowIndex = i + 1; break; }
  }

  const rowContent = [appData.id, JSON.stringify(appData), new Date().toISOString()];
  if (rowIndex > -1) {
    sheet.getRange(rowIndex, 1, 1, 3).setValues([rowContent]);
  } else {
    sheet.appendRow(rowContent);
  }
  return ContentService.createTextOutput(JSON.stringify({ status: "success" })).setMimeType(ContentService.MimeType.JSON);
}
```
4. Click **Deploy** > **New Deployment**. Select **Web App**.
5. Set "Execute as" to **Me** and "Who has access" to **Anyone**.
6. Copy the **Web App URL**. You will need this for the code below.

Now, I will update your application code to connect to this script.

### Specification of Updates

1.  **New Service Layer**: Created `services/googleSheetService.ts` to handle all `fetch` requests to your Google Apps Script URL.
2.  **App.tsx Logic**: 
    *   Replaced `localStorage` with real-time fetching from the cloud.
    *   Added a `loading` state and a visual spinner to indicate data is being synced from the spreadsheet.
    *   Updated `handleCreateApplication` and `updateApplication` to perform "upserts" (Insert or Update) to the Google Sheet.
3.  **Error Handling**: Added checks for the `SCRIPT_URL`. If the URL is not provided, the app gracefully falls back to a message asking the user to configure the backend.

