import { Application } from '../types';

// IMPORTANT: Replace this with your actual Google Apps Script Web App URL
const SCRIPT_URL = ''; 

export const GoogleSheetService = {
  isEnabled: () => SCRIPT_URL.length > 0,

  fetchAll: async (): Promise<Application[]> => {
    if (!SCRIPT_URL) return [];
    try {
      const response = await fetch(SCRIPT_URL);
      if (!response.ok) throw new Error('Failed to fetch from Google Sheets');
      return await response.json();
    } catch (error) {
      console.error('Sheet Fetch Error:', error);
      return [];
    }
  },

  saveOrUpdate: async (app: Application): Promise<boolean> => {
    if (!SCRIPT_URL) return false;
    try {
      const response = await fetch(SCRIPT_URL, {
        method: 'POST',
        mode: 'no-cors', // Apps Script requires no-cors for simple deployments
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(app),
      });
      // With no-cors, we can't read the response body, but the data is sent.
      return true;
    } catch (error) {
      console.error('Sheet Save Error:', error);
      return false;
    }
  }
};

import React, { useState, useEffect } from 'react';
import { UserRole, Application, ApplicationStatus } from './types';
import Dashboard from './components/Dashboard';
import ApplicationWizard from './components/ApplicationWizard';
import RoleSwitcher from './components/RoleSwitcher';
import { GoogleSheetService } from './services/googleSheetService';

const App: React.FC = () => {
  const [currentUserRole, setCurrentUserRole] = useState<UserRole>(UserRole.APPLICANT);
  const [applications, setApplications] = useState<Application[]>([]);
  const [isCreating, setIsCreating] = useState(false);
  const [isLoading, setIsLoading] = useState(true);

  // Load data from Google Sheets on mount
  useEffect(() => {
    const loadData = async () => {
      setIsLoading(true);
      if (GoogleSheetService.isEnabled()) {
        const data = await GoogleSheetService.fetchAll();
        setApplications(data);
      } else {
        // Fallback to local storage if URL is not set yet
        const saved = localStorage.getItem('research_apps');
        if (saved) setApplications(JSON.parse(saved));
      }
      setIsLoading(false);
    };
    loadData();
  }, []);

  const handleCreateApplication = async (newApp: Application) => {
    // Optimistic UI update
    setApplications(prev => [newApp, ...prev]);
    setIsCreating(false);

    // Persist to Cloud
    if (GoogleSheetService.isEnabled()) {
      await GoogleSheetService.saveOrUpdate(newApp);
    } else {
      localStorage.setItem('research_apps', JSON.stringify([newApp, ...applications]));
    }
  };

  const updateApplication = async (updatedApp: Application) => {
    // Optimistic UI update
    setApplications(prev => prev.map(app => app.id === updatedApp.id ? updatedApp : app));

    // Persist to Cloud
    if (GoogleSheetService.isEnabled()) {
      await GoogleSheetService.saveOrUpdate(updatedApp);
    } else {
      const newApps = applications.map(app => app.id === updatedApp.id ? updatedApp : app);
      localStorage.setItem('research_apps', JSON.stringify(newApps));
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 px-6 py-4 flex justify-between items-center sticky top-0 z-50">
        <div className="flex items-center gap-3">
          <div className="bg-indigo-600 p-2 rounded-lg">
            <i className="fas fa-file-signature text-white text-xl"></i>
          </div>
          <div>
            <h1 className="font-bold text-xl text-slate-800 tracking-tight">ResFlow</h1>
            <p className="text-xs text-slate-500 font-medium uppercase tracking-wider">Research Approval System</p>
          </div>
        </div>

        <div className="flex items-center gap-6">
          {!GoogleSheetService.isEnabled() && (
            <div className="hidden lg:flex items-center gap-2 bg-amber-50 text-amber-700 px-3 py-1.5 rounded-full border border-amber-100 text-[10px] font-bold">
              <i className="fas fa-exclamation-triangle"></i>
              OFFLINE MODE (Local Storage)
            </div>
          )}
          <RoleSwitcher currentRole={currentUserRole} onRoleChange={setCurrentUserRole} />
          <div className="h-8 w-[1px] bg-slate-200 hidden md:block"></div>
          <div className="hidden md:flex items-center gap-2">
            <div className="w-8 h-8 rounded-full bg-slate-200 flex items-center justify-center text-slate-600 font-bold text-sm">
              {currentUserRole.charAt(0)}
            </div>
            <span className="text-sm font-medium text-slate-700">{currentUserRole.replace('_', ' ')}</span>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 container mx-auto px-4 py-8 max-w-7xl">
        {isLoading ? (
          <div className="flex flex-col items-center justify-center py-20 animate-pulse">
            <div className="w-12 h-12 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin mb-4"></div>
            <p className="text-slate-500 font-medium">Syncing with Google Sheets...</p>
          </div>
        ) : isCreating ? (
          <ApplicationWizard 
            onCancel={() => setIsCreating(false)} 
            onSubmit={handleCreateApplication}
          />
        ) : (
          <Dashboard 
            role={currentUserRole}
            applications={applications}
            onCreateNew={() => setIsCreating(true)}
            onUpdateApplication={updateApplication}
          />
        )}
      </main>

      <footer className="bg-white border-t border-slate-200 py-6 text-center text-slate-500 text-sm">
        <div className="flex flex-col items-center gap-2">
          <span>&copy; {new Date().getFullYear()} ResFlow Systems. All Rights Reserved.</span>
          {GoogleSheetService.isEnabled() && (
            <span className="text-[10px] flex items-center gap-1 text-emerald-500 font-bold">
              <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
              Live Data Connected
            </span>
          )}
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { UserRole, Application, ApplicationStatus, ReviewData, REVIEWER_LIST, ReviewRating } from '../types';
import ApplicationCard from './ApplicationCard';
import StageActions from './StageActions';

interface DashboardProps {
  role: UserRole;
  applications: Application[];
  onCreateNew: () => void;
  onUpdateApplication: (app: Application) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ role, applications, onCreateNew, onUpdateApplication }) => {
  const [selectedApp, setSelectedApp] = useState<Application | null>(null);

  const handlePrint = () => {
    window.print();
  };

  // Filter logic: Reviewers only see applications that specifically selected them
  const filteredApps = applications.filter(app => {
    if (role === UserRole.APPLICANT) return true; 

    if (REVIEWER_LIST.includes(role)) {
      const isSelectedForThisApp = app.selectedReviewers.includes(role);
      const isUnderReview = app.status === ApplicationStatus.SUBMITTED || app.status === ApplicationStatus.UNDER_REVIEW;
      return isUnderReview && isSelectedForThisApp;
    }

    if (role === UserRole.HOD) {
      return app.status === ApplicationStatus.HOD_PENDING;
    }

    if (role === UserRole.DIRECTOR) {
      return app.status === ApplicationStatus.DIRECTOR_PENDING;
    }

    return false;
  });

  return (
    <div className="space-y-6">
      {/* Dashboard Header - Hidden on Print */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 print:hidden">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">
            {role === UserRole.APPLICANT ? 'My Applications' : 'Pending Tasks'}
          </h2>
          <p className="text-slate-500">Manage research paper submission and approval cycles.</p>
        </div>
        {role === UserRole.APPLICANT && (
          <button 
            onClick={onCreateNew}
            className="flex items-center justify-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white px-5 py-2.5 rounded-lg font-semibold shadow-sm transition-all"
          >
            <i className="fas fa-plus"></i>
            New Application
