import React, { useState, useEffect } from 'react';
import { UserRole, Application, ApplicationStatus } from './types';
import Dashboard from './components/Dashboard';
import ApplicationWizard from './components/ApplicationWizard';
import RoleSwitcher from './components/RoleSwitcher';
import { GoogleSheetService } from './services/googleSheetService';

const App: React.FC = () => {
  const [currentUserRole, setCurrentUserRole] = useState<UserRole>(UserRole.APPLICANT);
  const [applications, setApplications] = useState<Application[]>([]);
  const [isCreating, setIsCreating] = useState(false);
  const [isLoading, setIsLoading] = useState(true);

  // Load data from Google Sheets on mount
  useEffect(() => {
    const loadData = async () => {
      setIsLoading(true);
      if (GoogleSheetService.isEnabled()) {
        const data = await GoogleSheetService.fetchAll();
        setApplications(data);
      } else {
        // Fallback to local storage if URL is not set yet
        const saved = localStorage.getItem('research_apps');
        if (saved) setApplications(JSON.parse(saved));
      }
      setIsLoading(false);
    };
    loadData();
  }, []);

  const handleCreateApplication = async (newApp: Application) => {
    // Optimistic UI update
    setApplications(prev => [newApp, ...prev]);
    setIsCreating(false);

    // Persist to Cloud
    if (GoogleSheetService.isEnabled()) {
      await GoogleSheetService.saveOrUpdate(newApp);
    } else {
      localStorage.setItem('research_apps', JSON.stringify([newApp, ...applications]));
    }
  };

  const updateApplication = async (updatedApp: Application) => {
    // Optimistic UI update
    setApplications(prev => prev.map(app => app.id === updatedApp.id ? updatedApp : app));

    // Persist to Cloud
    if (GoogleSheetService.isEnabled()) {
      await GoogleSheetService.saveOrUpdate(updatedApp);
    } else {
      const newApps = applications.map(app => app.id === updatedApp.id ? updatedApp : app);
      localStorage.setItem('research_apps', JSON.stringify(newApps));
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      {/* Header - Hidden on Print */}
      <header className="bg-white border-b border-slate-200 px-6 py-4 flex justify-between items-center sticky top-0 z-50 print:hidden">
        <div className="flex items-center gap-3">
          <div className="bg-indigo-600 p-2 rounded-lg">
            <i className="fas fa-file-signature text-white text-xl"></i>
          </div>
          <div>
            <h1 className="font-bold text-xl text-slate-800 tracking-tight">ResFlow</h1>
            <p className="text-xs text-slate-500 font-medium uppercase tracking-wider">Research Approval System</p>
          </div>
        </div>

        <div className="flex items-center gap-6">
          {!GoogleSheetService.isEnabled() && (
            <div className="hidden lg:flex items-center gap-2 bg-amber-50 text-amber-700 px-3 py-1.5 rounded-full border border-amber-100 text-[10px] font-bold">
              <i className="fas fa-exclamation-triangle"></i>
              OFFLINE MODE (Local Storage)
            </div>
          )}
          <RoleSwitcher currentRole={currentUserRole} onRoleChange={setCurrentUserRole} />
          <div className="h-8 w-[1px] bg-slate-200 hidden md:block"></div>
          <div className="hidden md:flex items-center gap-2">
            <div className="w-8 h-8 rounded-full bg-slate-200 flex items-center justify-center text-slate-600 font-bold text-sm">
              {currentUserRole.charAt(0)}
            </div>
            <span className="text-sm font-medium text-slate-700">{currentUserRole.replace('_', ' ')}</span>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 container mx-auto px-4 py-8 max-w-7xl print:max-w-none print:p-0">
        {isLoading ? (
          <div className="flex flex-col items-center justify-center py-20 animate-pulse print:hidden">
            <div className="w-12 h-12 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin mb-4"></div>
            <p className="text-slate-500 font-medium">Syncing with Google Sheets...</p>
          </div>
        ) : isCreating ? (
          <ApplicationWizard 
            onCancel={() => setIsCreating(false)} 
            onSubmit={handleCreateApplication}
          />
        ) : (
          <Dashboard 
            role={currentUserRole}
            applications={applications}
            onCreateNew={() => setIsCreating(true)}
            onUpdateApplication={updateApplication}
          />
        )}
      </main>

      <footer className="bg-white border-t border-slate-200 py-6 text-center text-slate-500 text-sm print:hidden">
        <div className="flex flex-col items-center gap-2">
          <span>&copy; {new Date().getFullYear()} ResFlow Systems. All Rights Reserved.</span>
          {GoogleSheetService.isEnabled() && (
            <span className="text-[10px] flex items-center gap-1 text-emerald-500 font-bold">
              <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
              Live Data Connected
            </span>
          )}
        </div>
      </footer>
    </div>
  );
};

export default App;

