Yes, it is absolutely possible and highly recommended! Separating the data into individual columns makes the spreadsheet much more useful for generating reports, filtering by applicant name, or tracking statuses directly in Google Sheets.

I have updated the logic to map each field (Title, Status, Name, Email, etc.) to its own column. For complex parts like "Team Members" or "Review Comments," I keep them as structured JSON within a single cell to ensure no data is lost while keeping the sheet clean.

### Updated Google Apps Script
You should replace the previous code in your **Google Apps Script** editor with this version. It now handles the mapping of individual columns:

```javascript
const SHEET_NAME = "Applications";
// Define the column order explicitly
const HEADERS = [
  "id", "applicantName", "applicantIdCard", "applicantEmail", "applicantPhone",
  "teamName", "teamMembers", "researchTitle", "researchLink", "eventName",
  "eventLocation", "eventDate", "eventLevel", "submissionDate", "status",
  "selectedReviewers", "reviews", "hodStatus", "hodComments", "hodDate",
  "directorStatus", "directorComments", "directorDate", "lastUpdated"
];

function doGet() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_NAME) || SpreadsheetApp.getActiveSpreadsheet().insertSheet(SHEET_NAME);
  const data = sheet.getDataRange().getValues();
  if (data.length <= 1) return ContentService.createTextOutput("[]").setMimeType(ContentService.MimeType.JSON);

  const apps = data.slice(1).map(row => {
    let obj = {};
    HEADERS.forEach((header, index) => {
      let value = row[index];
      // Parse JSON strings back into objects/arrays for the frontend
      if (["teamMembers", "selectedReviewers", "reviews"].includes(header)) {
        try { value = JSON.parse(value); } catch(e) { value = (header === "reviews" ? {} : []); }
      }
      obj[header] = value;
    });
    return obj;
  });
  return ContentService.createTextOutput(JSON.stringify(apps)).setMimeType(ContentService.MimeType.JSON);
}

function doPost(e) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_NAME) || SpreadsheetApp.getActiveSpreadsheet().insertSheet(SHEET_NAME);
  const appData = JSON.parse(e.postData.contents);
  const data = sheet.getDataRange().getValues();

  // Create the row array based on our header order
  const rowValues = HEADERS.map(header => {
    if (header === "lastUpdated") return new Date().toISOString();
    let val = appData[header];
    // Stringify nested objects for storage in a single cell
    if (["teamMembers", "selectedReviewers", "reviews"].includes(header)) {
      return JSON.stringify(val || (header === "reviews" ? {} : []));
    }
    return val || "";
  });

  let rowIndex = -1;
  for (let i = 1; i < data.length; i++) {
    if (data[i][0] === appData.id) { rowIndex = i + 1; break; }
  }

  if (rowIndex > -1) {
    sheet.getRange(rowIndex, 1, 1, HEADERS.length).setValues([rowValues]);
  } else {
    // If it's a new sheet, add headers first
    if (data.length === 1 && data[0][0] === "") {
       sheet.getRange(1, 1, 1, HEADERS.length).setValues([HEADERS]);
    }
    sheet.appendRow(rowValues);
  }
  return ContentService.createTextOutput(JSON.stringify({ status: "success" })).setMimeType(ContentService.MimeType.JSON);
}
```

### Application Updates
I have also implemented the **Print Documentation** feature. It generates a professional, formal report including all applicant info, team details, and the full audit trail of approvals.

