To ensure your data is stored in individual columns in Google Sheets rather than a single JSON block, you need to use a specific `doPost` function in your Google Apps Script that maps the incoming keys to specific sheet columns.

Here is the **Updated Google Apps Script** code. **Please copy and paste this into your Apps Script editor, Save, and Re-deploy as a "New Version"**:

```javascript
const SHEET_NAME = "Applications";
// This array defines the exact order of columns in your Google Sheet
const HEADERS = [
  "id", "applicantName", "applicantIdCard", "applicantEmail", "applicantPhone",
  "teamName", "teamMembers", "researchTitle", "researchLink", "eventName",
  "eventLocation", "eventDate", "eventLevel", "submissionDate", "status",
  "selectedReviewers", "reviews", "hodStatus", "hodComments", "hodDate",
  "directorStatus", "directorComments", "directorDate"
];

function doGet() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_NAME) || SpreadsheetApp.getActiveSpreadsheet().insertSheet(SHEET_NAME);
  const data = sheet.getDataRange().getValues();
  if (data.length <= 1) return ContentService.createTextOutput("[]").setMimeType(ContentService.MimeType.JSON);

  const apps = data.slice(1).map(row => {
    let obj = {};
    HEADERS.forEach((header, index) => {
      let value = row[index];
      // Parse JSON strings back into objects/arrays for the frontend
      if (["teamMembers", "selectedReviewers", "reviews"].includes(header)) {
        try { value = JSON.parse(value); } catch(e) { value = (header === "reviews" ? {} : []); }
      }
      obj[header] = value;
    });
    return obj;
  });
  return ContentService.createTextOutput(JSON.stringify(apps)).setMimeType(ContentService.MimeType.JSON);
}

function doPost(e) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_NAME) || SpreadsheetApp.getActiveSpreadsheet().insertSheet(SHEET_NAME);
  const appData = JSON.parse(e.postData.contents);
  const data = sheet.getDataRange().getValues();

  // Map incoming data to the defined column order
  const rowValues = HEADERS.map(header => {
    let val = appData[header];
    // Keep complex structures as JSON inside the cell
    if (["teamMembers", "selectedReviewers", "reviews"].includes(header)) {
      return JSON.stringify(val || (header === "reviews" ? {} : []));
    }
    return val || "";
  });

  let rowIndex = -1;
  // Check if we are updating an existing application by ID
  for (let i = 1; i < data.length; i++) {
    if (data[i][0] === appData.id) { rowIndex = i + 1; break; }
  }

  if (rowIndex > -1) {
    sheet.getRange(rowIndex, 1, 1, HEADERS.length).setValues([rowValues]);
  } else {
    // If sheet is empty, add headers first
    if (data.length === 1 && data[0][0] === "") {
       sheet.getRange(1, 1, 1, HEADERS.length).setValues([HEADERS]);
    }
    sheet.appendRow(rowValues);
  }
  return ContentService.createTextOutput(JSON.stringify({ status: "success" }))
    .setMimeType(ContentService.MimeType.JSON);
}
```

