function doGet() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let sheet = ss.getSheetByName(SHEET_NAME) || ss.insertSheet(SHEET_NAME);
  const data = sheet.getDataRange().getValues();

  if (data.length <= 1) return createJsonResponse([]);

  const results = data.slice(1).map(row => {
    let obj = {};
    HEADERS.forEach((header, index) => {
      let value = row[index];
      // Convert JSON strings back to objects for the frontend where necessary
      if (["teamMembers", "selectedReviewers", "reviews"].includes(header)) {
        try { value = JSON.parse(value); } catch(e) { value = header === "reviews" ? {} : []; }
      }
      obj[header] = value;
    });
    return obj;
  });

  return createJsonResponse(results);
}

function doPost(e) {
  try {
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    let sheet = ss.getSheetByName(SHEET_NAME) || ss.insertSheet(SHEET_NAME);
    const payload = JSON.parse(e.postData.contents);
    const data = sheet.getDataRange().getValues();

    // Create the row by mapping payload keys to our HEADERS array
    const rowValues = HEADERS.map(header => {
      let val = payload[header];
      // If the value is an object or array (like teamMembers), stringify it for the cell
      if (typeof val === 'object' && val !== null) {
        return JSON.stringify(val);
      }
      return val || "";
    });

    // Find if application exists to update it, otherwise append
    let rowIndex = -1;
    for (let i = 1; i < data.length; i++) {
      if (data[i][0] == payload.id) {
        rowIndex = i + 1;
        break;
      }
    }

    if (rowIndex > -1) {
      sheet.getRange(rowIndex, 1, 1, HEADERS.length).setValues([rowValues]);
    } else {
      // Ensure headers exist if it's a new sheet
      if (data.length === 1 && data[0][0] === "") {
        sheet.getRange(1, 1, 1, HEADERS.length).setValues([HEADERS]);
      }
      sheet.appendRow(rowValues);
    }

    return createJsonResponse({ status: "success" });
  } catch (err) {
    return createJsonResponse({ status: "error", message: err.toString() });
  }
}

function createJsonResponse(data) {
  return ContentService.createTextOutput(JSON.stringify(data))
    .setMimeType(ContentService.MimeType.JSON);
}
