export const GoogleSheetService = {
  isEnabled: () => SCRIPT_URL.length > 0 && !SCRIPT_URL.includes('your-actual-url'),

  fetchAll: async (): Promise<Application[]> => {
    if (!SCRIPT_URL || SCRIPT_URL.includes('your-actual-url')) return [];
    try {
      // Prevent browser caching of results
      const response = await fetch(`${SCRIPT_URL}?t=${Date.now()}`);
      if (!response.ok) throw new Error('Failed to fetch from Google Sheets');
      const data = await response.json();
      return Array.isArray(data) ? data : [];
    } catch (error) {
      console.error('Sheet Fetch Error:', error);
      return [];
    }
  },

  saveOrUpdate: async (app: Application): Promise<boolean> => {
    if (!SCRIPT_URL || SCRIPT_URL.includes('your-actual-url')) return false;
    try {
      /**
       * We use 'no-cors' mode because Apps Script doesn't support the OPTIONS preflight
       * request required for standard JSON POSTs. We send the body as a JSON string
       * and the script parses it on arrival.
       */
      await fetch(SCRIPT_URL, {
        method: 'POST',
        mode: 'no-cors',
        headers: {
          'Content-Type': 'text/plain', 
        },
        body: JSON.stringify(app),
      });
      return true;
    } catch (error) {
      console.error('Sheet Save Error:', error);
      return false;
    }
  }
};

