import React from 'react';
import { Application, ApplicationStatus } from '../types';

interface ApplicationCardProps {
  app: Application;
  isActive: boolean;
  onClick: () => void;
}

const ApplicationCard: React.FC<ApplicationCardProps> = ({ app, isActive, onClick }) => {
  const getStatusColor = (status: ApplicationStatus) => {
    if (!status) return 'bg-slate-100 text-slate-700 border-slate-200';
    switch (status) {
      case ApplicationStatus.APPROVED: return 'bg-emerald-100 text-emerald-700 border-emerald-200';
      case ApplicationStatus.REJECTED: return 'bg-rose-100 text-rose-700 border-rose-200';
      case ApplicationStatus.HOD_PENDING: return 'bg-amber-100 text-amber-700 border-amber-200';
      case ApplicationStatus.DIRECTOR_PENDING: return 'bg-blue-100 text-blue-700 border-blue-200';
      default: return 'bg-slate-100 text-slate-700 border-slate-200';
    }
  };

  return (
    <div 
      onClick={onClick}
      className={`p-5 rounded-xl border transition-all cursor-pointer ${
        isActive 
          ? 'bg-indigo-50 border-indigo-200 shadow-md ring-1 ring-indigo-500' 
          : 'bg-white border-slate-200 hover:border-indigo-300 hover:shadow-sm'
      }`}
    >
      <div className="flex justify-between items-start mb-3">
        <span className={`px-2.5 py-0.5 rounded-full text-[10px] font-bold uppercase border ${getStatusColor(app.status)}`}>
          {app.status?.replace('_', ' ') || 'UNKNOWN'}
        </span>
        <span className="text-[10px] font-medium text-slate-400">
          ID: {app.id?.slice(0, 8) || 'N/A'}
        </span>
      </div>
      <h4 className="font-bold text-slate-800 line-clamp-1">{app.researchTitle || 'Untitled Research'}</h4>
      <p className="text-sm text-slate-500 mt-1">{app.applicantName || 'Anonymous'}</p>

      <div className="mt-4 flex items-center justify-between">
        <div className="flex -space-x-2">
          {app.teamMembers?.slice(0, 3).map((m, i) => (
            <div key={i} className="w-6 h-6 rounded-full bg-indigo-100 border-2 border-white flex items-center justify-center text-[10px] font-bold text-indigo-600">
              {m.name?.charAt(0) || '?'}
            </div>
          ))}
          {app.teamMembers?.length > 3 && (
            <div className="w-6 h-6 rounded-full bg-slate-100 border-2 border-white flex items-center justify-center text-[10px] font-bold text-slate-600">
              +{app.teamMembers.length - 3}
            </div>
          )}
        </div>
        <div className="text-[11px] font-medium text-slate-400 italic">
          {app.submissionDate ? new Date(app.submissionDate).toLocaleDateString() : 'N/A'}
        </div>
      </div>
    </div>
  );
};

